function AddModelModal({ catalog: initialCatalog, providers: _, serviceId, onClose, onSaved }: { catalog: CatalogOffering[]; providers: { id: string; name: string; modelCount: number }[]; serviceId: string; onClose: () => void; onSaved: () => void }) {
  const { t } = useI18n()
  const [savedAccounts, setSavedAccounts] = useState<SaasProvider[]>([])
  const [useExisting, setUseExisting] = useState(true)
  const [selectedAccountId, setSelectedAccountId] = useState<string>('')
  const [draft, setDraft] = useState<DraftEndpoint>(emptyEndpoint())
  const [visible, setVisible] = useState(false)
  const [advanced, setAdvanced] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [testStatus, setTestStatus] = useState<'idle' | 'testing' | 'passed' | 'failed'>('idle')
  const [testMsg, setTestMsg] = useState('')
  const [modelSearch, setModelSearch] = useState('')
  const [selectedModelIds, setSelectedModelIds] = useState<string[]>([])
  const [openRouterModels, setOpenRouterModels] = useState<CatalogOffering[]>([])

  useEffect(() => {
    let active = true
    const timer = setTimeout(async () => {
    const loadMarket = async () => {
      try {
        const queryParam = modelSearch.trim() ? `&search=${encodeURIComponent(modelSearch.trim())}` : ''
        const res = await saasFetch<{ models?: Array<{ id: string; name: string; prompt_price_per_1m: number; completion_price_per_1m: number; context_length: number; description: string | null }> }>(`/api/saas/openrouter/market?page_size=1000${queryParam}`)
        if (active && res.data?.models) {
          const mapped: CatalogOffering[] = res.data.models.map((m) => ({
            provider_id: 'openrouter',
            provider_name: 'OpenRouter',
            endpoint_id: `openrouter-${m.id}`,
            endpoint_key: 'openrouter',
            region: 'global',
            base_url: 'https://openrouter.ai/api/v1',
            price_currency: 'USD',
            model: m.id,
            model_name: m.name,
            description: m.description || '',
            input_price_per_1m: m.prompt_price_per_1m,
            output_price_per_1m: m.completion_price_per_1m,
            cache_read_price_per_1m: 0,
            cache_write_price_per_1m: 0,
            supports_tools: true,
            supports_vision: false,
            supports_reasoning: m.id.includes('r1') || m.id.includes('reasoning') || m.id.includes('o1') || m.id.includes('o3'),
            context_length: m.context_length,
          }))
          setOpenRouterModels(mapped)
        }
      } catch (_) {}
    }
    loadMarket()
    })
    return () => { active = false; clearTimeout(timer) }
  }, [modelSearch])

  const fullCatalog = useMemo(() => {
    if (openRouterModels.length === 0) {
      if (!modelSearch.trim()) return initialCatalog
      const q = modelSearch.toLowerCase()
      return initialCatalog.filter((m) => m.model.toLowerCase().includes(q) || (m.model_name && m.model_name.toLowerCase().includes(q)))
    }
    const nonOr = initialCatalog.filter((item) => item.provider_id !== 'openrouter')
    return [...nonOr, ...openRouterModels]
  }, [initialCatalog, openRouterModels, modelSearch])

  useEffect(() => {
    saasFetch<SaasProvider[]>('/api/saas/providers').then((res) => {
      const list = res.data || []
      setSavedAccounts(list)
      if (list.length > 0) {
        setSelectedAccountId(list[0].id)
        setUseExisting(true)
        const acc = list[0]
        setDraft((curr) => ({
          ...curr,
          provider_type: acc.provider_type,
          protocol: acc.protocol || 'openai',
          base_url: acc.base_url,
          upstream_model_id: '',
          input_price_per_1m: '',
          output_price_per_1m: '',
          capability_score: '0.70',
          context_length: '',
        }))
      } else {
        setUseExisting(false)
      }
    }).catch(() => {
      setUseExisting(false)
    })
  }, [])

  const selectedAccount = savedAccounts.find((a) => a.id === selectedAccountId)
  const currentProviderType = useExisting ? (selectedAccount?.provider_type || 'custom') : draft.provider_type
  const models = useMemo(() => {
    return fullCatalog.filter((item) => item.provider_id === currentProviderType)
  }, [fullCatalog, currentProviderType])

  const filteredModels = useMemo(() => {
    const query = modelSearch.trim().toLowerCase()
    if (!query) return models

    // Relevance scoring:
    // Exact ID match: 100
    // ID starts with query or contains `/{query}`: 80
    // Name contains query: 60
    // ID contains query: 40
    const scored = models.map((m) => {
      const id = (m.model || '').toLowerCase()
      const name = (m.model_name || '').toLowerCase()
      let score = 0

      if (id === query || id === `deepseek/${query}`) {
        score = 100
      } else if (id.startsWith(query) || id.startsWith(`${query}/`) || id.includes(`/${query}`)) {
        score = 80
      } else if (name.startsWith(query) || name.includes(` ${query}`)) {
        score = 70
      } else if (name.includes(query)) {
        score = 50
      } else if (id.includes(query)) {
        score = 40
      }

      return { model: m, score }
    })

    return scored
      .filter((item) => item.score > 0)
      .sort((a, b) => b.score - a.score)
      .map((item) => item.model)
  }, [models, modelSearch])

  const formatPrice = (val: number) => {
    if (val === 0) return 'FREE'
    if (val < 0.0001) return `<$0.0001`
    const rounded = Number(val.toPrecision(4))
    return `$${rounded}`
  }

  const accountOptions = savedAccounts.map((a) => ({
    id: a.id,
    name: `${a.name} (${a.provider_type} • ${a.protocol})`,
  }))

  const presetProviderOptions = [
    { id: 'openrouter', name: 'OpenRouter' },
    { id: 'deepseek', name: 'DeepSeek' },
    { id: 'openai', name: 'OpenAI' },
    { id: 'anthropic', name: 'Anthropic' },
    { id: 'aliyun', name: 'Aliyun Bailian' },
    { id: 'custom', name: t('services.custom_provider') || 'Custom provider' },
  ]
  const selectedPresetProvider = presetProviderOptions.find((p) => p.id === draft.provider_type) || presetProviderOptions[0]

  const protocolOptions = [{ id: 'openai', name: 'OpenAI' }, { id: 'anthropic', name: 'Anthropic' }]
  const selectedProtocol = protocolOptions.find((option) => option.id === draft.protocol) || protocolOptions[0]

  const patch = (value: Partial<DraftEndpoint>) => {
    setDraft((current) => ({ ...current, ...value }))
    setTestStatus('idle')
  }

  function handleAccountChange(opt: { id: string | number; name: string }) {
    const accId = String(opt.id)
    setSelectedAccountId(accId)
    const acc = savedAccounts.find((a) => a.id === accId)
    if (acc) {
      const first = fullCatalog.find((item) => item.provider_id === acc.provider_type)
      if (first) {
        setSelectedModelIds([first.model])
      } else {
        setSelectedModelIds([])
      }
      setDraft((curr) => ({
        ...curr,
        provider_type: acc.provider_type,
        protocol: acc.protocol || 'openai',
        base_url: acc.base_url,
        upstream_model_id: first?.model || '',
        input_price_per_1m: first ? String(first.input_price_per_1m) : '',
        output_price_per_1m: first ? String(first.output_price_per_1m) : '',
        capability_score: first ? inferDefaultCapability(first) : '0.70',
        context_length: first?.context_length ? String(first.context_length) : '',
      }))
    }
  }

  function chooseNewProviderPreset(option: { id: string | number; name: string }) {
    const provider = String(option.id)
    const first = fullCatalog.find((item) => item.provider_id === provider)
    const protocol = /anthropic|claude/i.test(provider) ? 'anthropic' : 'openai'
    if (first) {
      setSelectedModelIds([first.model])
    } else {
      setSelectedModelIds([])
    }
    setDraft({
      ...emptyEndpoint(),
      provider_type: provider,
      protocol,
      upstream_model_id: first?.model || '',
      base_url: first?.base_url || '',
      input_price_per_1m: first ? String(first.input_price_per_1m) : '',
      output_price_per_1m: first ? String(first.output_price_per_1m) : '',
      capability_score: first ? inferDefaultCapability(first) : '0.70',
      context_length: first?.context_length ? String(first.context_length) : '',
    })
    setAdvanced(hasCatalogDetails(first))
    setTestStatus('idle')
  }

  function toggleModelSelection(m: CatalogOffering) {
    setSelectedModelIds((prev) => {
      const exists = prev.includes(m.model)
      if (exists) {
        const next = prev.filter((id) => id !== m.model)
        if (draft.upstream_model_id === m.model) {
          const fallback = next.length > 0 ? next[0] : ''
          patch({ upstream_model_id: fallback })
        }
        return next
      } else {
        patch({
          upstream_model_id: m.model,
          base_url: useExisting ? (selectedAccount?.base_url || m.base_url) : m.base_url,
          input_price_per_1m: String(m.input_price_per_1m),
          output_price_per_1m: String(m.output_price_per_1m),
          capability_score: inferDefaultCapability(m),
          context_length: m.context_length ? String(m.context_length) : '',
        })
        return [...prev, m.model]

